layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.60){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.25; mv.xy += position.xy*.5; vP = position.xy; vU = u; gl_Position = projectionMatrix*mv; }

layers.fragment:
varying vec2 vP; varying float vU;
    void main(){
      float r = length(vP), a = atan(vP.y, vP.x), u = vU, peak = u < .07 ? 1. : 0.;
      float f = peak*3. + (1. - peak)*pow(max(0., 1. - (u - .07)/0.530), 1.4)*1.1;
      float core = exp(-r*r*(peak > .5 ? 5. : 12.)), rays = pow(abs(cos(a*3.)), 24.)*exp(-r*3.5)*peak;   // brief starburst on the peak
      vec3 o = vec3(1., .98, .94)*(core + rays*.8)*f*smoothstep(1., .8, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
